--DS d_ds_script_mx_sat_info_hdr
SELECT 'MXSATHXDET' mxsathdrdef,invoice_iva_tax.invoice_no, COALESCE(invoice_iva_tax.account_digits, ship_to_iva_tax.account_digits, customer_iva_tax.account_digits, '') AS account_digits,cfdi_usage_mx.cfdi_usage_cd,cfdi_usage_mx.cfdi_usage_desc,CASE WHEN invoice_hdr.invoice_adjustment_type != 'P' THEN CASE WHEN (((NOT payment_method_mx.payment_method_cd IS NULL AND payment_method_mx.payment_method_cd = 'PPD') OR (((ISNULL(inv_remittances.payment_amount,0) <> invoice_hdr.total_amount) AND (invoice_hdr.total_amount <> 0)) AND (ISNULL(invoice_hdr.downpayment_applied,0) >= 0))) AND(not ((COALESCE(invoice_hdr.total_amount, 0) < 0 AND ( invoice_hdr.invoice_adjustment_type = 'I' )))))THEN (SELECT payment_type_mx_desc FROM payment_type_mx WHERE payment_type_mx_id = 99) ELSE COALESCE(CONVERT(VARCHAR, ( SELECT TOP 1 payment_type_mx.payment_type_mx_desc AS 'data()' FROM oe_hdr AS order_header INNER JOIN remittances ON ( remittances.order_no = order_header.order_no ) INNER JOIN ar_payment_details ON ( remittances.payment_number = ar_payment_details.payment_number ) INNER JOIN payment_types ON ( payment_types.payment_type_id = ar_payment_details.payment_type_id ) INNER JOIN payment_types_x_payment_type_mx ON ( payment_types.company_id = payment_types_x_payment_type_mx.company_id AND payment_types.payment_type_id = payment_types_x_payment_type_mx.payment_type_id ) INNER JOIN payment_type_mx ON payment_types_x_payment_type_mx.payment_type_mx_uid = payment_type_mx.payment_type_mx_uid WHERE payment_type_mx.payment_type_mx_uid IS NOT NULL AND order_header.order_no = oe_hdr.order_no ORDER BY ar_payment_details.payment_amount DESC )), NULLIF(customer.class_5id, ''), '01') END ELSE COALESCE((SELECT TOP 1 coalesce(payment_type_mx.payment_type_mx_desc,convert(varchar,payment_types.payment_type_desc)) AS 'data()' FROM oe_hdr AS oe_pay LEFT JOIN remittances ON ( remittances.order_no = oe_pay.order_no ) LEFT JOIN ar_payment_details ON ( remittances.payment_number = ar_payment_details.payment_number ) LEFT JOIN payment_types ON ( payment_types.payment_type_id = ar_payment_details.payment_type_id ) LEFT JOIN payment_types_x_payment_type_mx ON (payment_types.company_id = payment_types_x_payment_type_mx.company_id AND payment_types.payment_type_id = payment_types_x_payment_type_mx.payment_type_id) LEFT JOIN payment_type_mx ON payment_types_x_payment_type_mx.payment_type_mx_uid = payment_type_mx.payment_type_mx_uid WHERE oe_pay.order_no = oe_hdr.order_no ORDER BY ar_payment_details.payment_amount DESC),(select payment_type_mx_descfrom payment_types_x_payment_type_mxinner join payment_type_mx ON (payment_types_x_payment_type_mx.payment_type_mx_uid = payment_type_mx.payment_type_mx_uid)where payment_type_id = COALESCE(ship_to_iva_tax.payment_type_id, customer_iva_tax.payment_type_id) )) END AS payment_type_mx_desc ,CASE WHEN invoice_hdr.invoice_adjustment_type != 'P'THEN CASE WHEN (payment_method_mx.payment_method_cd IS NULL OR payment_method_mx.payment_method_cd = '')THENCASE WHEN ((inv_remittances.payment_amount = invoice_hdr.total_amount) OR (invoice_hdr.total_amount = 0))AND (NOT ISNULL(invoice_hdr.downpayment_applied,0) < 0)OR (invoice_hdr.invoice_adjustment_type = 'C')THEN'PUE'ELSE'PPD'ENDELSEpayment_method_mx.payment_method_cdEND ELSE'PUE' END AS payment_method_cd, CASE WHEN invoice_hdr.invoice_adjustment_type != 'P'THEN CASE WHEN (payment_method_mx.payment_method_cd IS NULL OR payment_method_mx.payment_method_cd = '')THENCASE WHEN ((inv_remittances.payment_amount = invoice_hdr.total_amount) OR (invoice_hdr.total_amount = 0))AND (NOT ISNULL(invoice_hdr.downpayment_applied,0) < 0)OR (invoice_hdr.invoice_adjustment_type = 'C')THEN'Pago en una sola exhibición'ELSE'Pago en parcialidades o diferido'ENDELSEpayment_method_mx.payment_method_descEND ELSE'Pago en una sola exhibición' END AS payment_method_desc, COALESCE(invoice_iva_tax.leyenda_fiscal_1, customer_iva_tax.leyenda_fiscal_1, '') AS leyenda_fiscal_1FROM invoice_iva_taxLEFT JOIN cfdi_usage_mx ON invoice_iva_tax.cfdi_usage_mx_uid = cfdi_usage_mx.cfdi_usage_mx_uid LEFT JOIN payment_method_mx ON invoice_iva_tax.payment_method_mx_uid = payment_method_mx.payment_method_mx_uidLEFT JOIN payment_types ON ( payment_types.payment_type_id = invoice_iva_tax.payment_type_id )LEFT JOIN payment_types_x_payment_type_mx ON ( payment_types.company_id = payment_types_x_payment_type_mx.company_id AND payment_types.payment_type_id = payment_types_x_payment_type_mx.payment_type_id)LEFT JOIN payment_type_mx ON payment_types_x_payment_type_mx.payment_type_mx_uid = payment_type_mx.payment_type_mx_uidLEFT JOIN invoice_hdr ON (invoice_hdr.company_no = invoice_iva_tax.company_id AND invoice_hdr.invoice_no = invoice_iva_tax.invoice_no)LEFT JOIN (SELECT invoice_no,SUM(payment_amount) AS payment_amount FROM remittances_detail GROUP BY invoice_no) AS inv_remittancesON inv_remittances.invoice_no = invoice_iva_tax.invoice_noLEFT JOIN oe_hdr ON ( oe_hdr.order_no = invoice_hdr.order_no AND oe_hdr.company_id = invoice_hdr.company_no)LEFT JOIN customer ON ( customer.company_id = invoice_hdr.company_no )AND ( customer.customer_id = invoice_hdr.customer_id_number )AND ( customer.delete_flag = 'N' )LEFT JOIN ship_to_iva_tax ON ( invoice_hdr.company_no = ship_to_iva_tax.company_idAND invoice_hdr.ship_to_id = ship_to_iva_tax.ship_to_id)LEFT JOIN customer_iva_tax ON ( invoice_hdr.customer_id_number = customer_iva_tax.customer_id )AND ( invoice_hdr.company_no = customer_iva_tax.company_id )AND ( customer_iva_tax.iva_taxable_flag = 'Y' )WHERE invoice_iva_tax.invoice_no IN ('3069750')